@Configuration
@EnableWebSocketMessageBroker
public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {
    public void registerStompEndpoints(StompEndpointRegistry registry) {
        registry.addEndpoint("/ws");                 // clients connect to ws(s)://host/ws
    }
    public void configureMessageBroker(MessageBrokerRegistry registry) {
        registry.enableSimpleBroker("/topic");       // in-memory broker
    }
}

@Service
class OrderTracker {
    private final SimpMessagingTemplate messages;
    OrderTracker(SimpMessagingTemplate messages) { this.messages = messages; }

    void statusChanged(Long orderId, String status) {
        messages.convertAndSend("/topic/orders/" + orderId, status);   // push to subscribers
    }
}

