@PostMapping("/payments")
ResponseEntity<PaymentResponse> pay(@RequestHeader("Idempotency-Key") String key,
                                    @Valid @RequestBody PaymentRequest req) {
    // 1. Reserve the key before charging: INSERT with UNIQUE(key)
    if (!idempotency.reserve(key)) {
        return idempotency.savedResponse(key)
            .map(resp -> ResponseEntity.status(HttpStatus.CREATED).body(resp))     // same status
            .orElseGet(() -> ResponseEntity.status(HttpStatus.CONFLICT).build());  // still running
    }
    // 2. Only the request that reserved the key processes it
    PaymentResponse resp = service.pay(req);
    idempotency.complete(key, resp);
    return ResponseEntity.status(HttpStatus.CREATED).body(resp);
}

